def try(label, json)
  ActiveRecord::Base.transaction do
    before = [Quiz.count, Question.count, Option.count]
    import = QuizImport.new(json: json)
    ok = import.save
    after = [Quiz.count, Question.count, Option.count]
    puts "#{label}: saved=#{ok} delta=#{after.zip(before).map { _1 - _2 }} errors=#{import.errors.full_messages.inspect}"
    puts "   => " + QuizExport.new(import.quiz.reload).to_json.gsub(/\s+/, " ") if ok
    raise ActiveRecord::Rollback
  end
end
